import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch } from 'react-redux';
import { useSearchParams } from 'react-router-dom';
import {
  Button,
  DEFAULT_CATALOG_LIST_TABLE_CONFIG,
  ErpListHeaderFilters,
  LinCatalogDataGrid,
  LinCatalogHistoryModal,
  LinCatalogListPagination,
  LinCatalogRowActionMenu,
  LinCatalogUiSchemaEditorModal,
  LinListFilterField,
  LinPageLayout,
  SearchInput,
  SearchTextInput,
  buildCatalogRowMenuItems,
  catalogListTableConfigFromSchema,
  dispatchAppToast,
  useCatalogHistoryModal,
  useErpListSelection,
  useServerPagedListLoading,
  type ErpListTableConfig,
  type LinCatalogRowMenuItem,
} from '@linm-soft-org/linm-web-common-components';
import { useInAppNavigate } from '../../router/navigateInAppPath';
import { useCatalogUiSchema } from '../../hooks/useCatalogUiSchema';
import { catalogUiSchemaService } from '../../services/catalogUiSchema/catalogUiSchemaService';
import { notificationService } from '../../services/notification/notificationService';
import { opsListPermissions } from '../../services/notification/permissions';
import type {
  NotificationDto,
  NotificationOverviewDto,
} from '../../services/notification/responseModel';
import {
  DIRECTION_LOOKUP,
  DIRECTION_LOOKUP_CONFIG,
  ORG_UNIT_LOOKUP,
  ORG_UNIT_LOOKUP_CONFIG,
  PRIORITY_LOOKUP,
  PRIORITY_LOOKUP_CONFIG,
  RECIPIENT_LOOKUP,
  STATUS_LOOKUP,
  STATUS_LOOKUP_CONFIG,
  TYPE_LOOKUP,
  TYPE_LOOKUP_CONFIG,
  lookupLabel,
} from '../../services/notification/lookups';
import {
  buildDynamicGridColumns,
  type UiListColumnBootstrap,
} from '../../utils/bootstrapCatalogUiSchema';
import styles from './NotificationListPage.module.css';
import { fromCatalogToolbar } from '../buildRmmsGenericToolbar';

const TEST_ID = 'rmms-ops-list';
const PAGE_ID = 'ops';
const CATALOG_KIND = 'ops-inbox';
const ROW_MENU_HINT_KEY = `${TEST_ID}-row-menu-hint-dismissed`;

const EMPTY_OVERVIEW: NotificationOverviewDto = {
  unreadCount: 0,
  staffOnline: 0,
  openIncidents: 0,
  woInProgress: 0,
};

function formatSentAt(iso?: string): string {
  if (!iso) return '—';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

const NotificationListPage: React.FC = () => {
  const dispatch = useDispatch();
  const catalogHistory = useCatalogHistoryModal();
  const navigate = useInAppNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const perms = opsListPermissions();
  const { schema, reload: reloadSchema } = useCatalogUiSchema(CATALOG_KIND);

  const [searchDraft, setSearchDraft] = useState('');
  const [statusDraft, setStatusDraft] = useState('');
  const [priorityDraft, setPriorityDraft] = useState('');
  const [typeDraft, setTypeDraft] = useState('');
  const [unreadDraft, setUnreadDraft] = useState('');
  const [directionDraft, setDirectionDraft] = useState('');
  const [orgDraft, setOrgDraft] = useState('');
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [priorityFilter, setPriorityFilter] = useState('');
  const [typeFilter, setTypeFilter] = useState('');
  const [unreadOnly, setUnreadOnly] = useState(false);
  const [directionFilter, setDirectionFilter] = useState('');
  const [orgFilter, setOrgFilter] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState<number>(50);
  const [items, setItems] = useState<NotificationDto[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [overview, setOverview] = useState<NotificationOverviewDto>(EMPTY_OVERVIEW);
  const [rowMenu, setRowMenu] = useState<{
    x: number;
    y: number;
    row: NotificationDto;
  } | null>(null);
  const [configOpen, setConfigOpen] = useState(false);
  const [tableConfig, setTableConfig] = useState<ErpListTableConfig>(() => ({
    ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
    ...catalogListTableConfigFromSchema(undefined),
    resizable: true,
  }));

  const {
    showTableLoading,
    pageLoading,
    pulseSearch,
    setLoadingMode,
    beginFetch,
    endFetch,
  } = useServerPagedListLoading();

  const load = useCallback(() => {
    beginFetch();
    Promise.all([
      notificationService.getList({
        search: search.trim() || undefined,
        status: statusFilter || undefined,
        priority: priorityFilter || undefined,
        type: typeFilter || undefined,
        unreadOnly: unreadOnly || undefined,
        direction: directionFilter || undefined,
        orgUnitCode: orgFilter || undefined,
        page,
        pageSize,
      }),
      notificationService.getOverview(),
    ])
      .then(([res, ov]) => {
        setItems(res.items);
        setTotalCount(res.totalCount);
        setOverview(ov);
      })
      .catch(() => {
        setItems([]);
        setTotalCount(0);
        setOverview(EMPTY_OVERVIEW);
      })
      .finally(() => endFetch());
  }, [
    search,
    statusFilter,
    priorityFilter,
    typeFilter,
    unreadOnly,
    directionFilter,
    orgFilter,
    page,
    pageSize,
    beginFetch,
    endFetch,
  ]);

  useEffect(() => {
    let cancelled = false;
    const t = window.setTimeout(() => {
      if (!cancelled) load();
    }, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, [load]);

  useEffect(() => {
    const form = searchParams.get('form');
    if (!form) return;
    const id = searchParams.get('id');
    if (form === 'create') {
      navigate('/chi-dao/tao-moi', { replace: true });
      return;
    }
    if (id && (form === 'edit' || form === 'view' || form === 'copy')) {
      if (form === 'copy') {
        navigate(`/chi-dao/tao-moi?copyFrom=${encodeURIComponent(id)}`, { replace: true });
        return;
      }
      const qs = form === 'edit' ? '?mode=edit' : '';
      navigate(`/chi-dao/${encodeURIComponent(id)}${qs}`, { replace: true });
      return;
    }
    setSearchParams({}, { replace: true });
  }, [searchParams, setSearchParams, navigate]);

  const listSelection = useErpListSelection<NotificationDto>({
    rows: items,
    totalCount,
    page,
    pageSize,
    getRowId: (r) => r.id,
  });
  const { activeRow, selectActiveRow, clearSelection } = listSelection;

  const applyFilters = useCallback(
    (
      nextSearch: string,
      nextStatus: string,
      nextPriority: string,
      nextType: string,
      nextUnread: string,
      nextDirection: string,
      nextOrg: string,
    ) => {
      pulseSearch(() => {
        setSearch(nextSearch.trim());
        setStatusFilter(nextStatus);
        setPriorityFilter(nextPriority);
        setTypeFilter(nextType);
        setUnreadOnly(nextUnread === '1');
        setDirectionFilter(nextDirection);
        setOrgFilter(nextOrg);
        setPage(1);
      });
    },
    [pulseSearch],
  );

  useEffect(() => {
    const t = window.setTimeout(() => {
      applyFilters(
        searchDraft,
        statusDraft,
        priorityDraft,
        typeDraft,
        unreadDraft,
        directionDraft,
        orgDraft,
      );
    }, 300);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- draft-only debounce
  }, [searchDraft, statusDraft, priorityDraft, typeDraft, unreadDraft, directionDraft, orgDraft]);

  const openRow = useCallback(
    (row: NotificationDto, mode: 'create' | 'edit' | 'view' | 'copy') => {
      selectActiveRow(row);
      if (mode === 'create') {
        navigate('/chi-dao/tao-moi');
        return;
      }
      if (mode === 'copy') {
        navigate(`/chi-dao/tao-moi?copyFrom=${encodeURIComponent(row.id)}`);
        return;
      }
      const qs = mode === 'edit' ? '?mode=edit' : '';
      navigate(`/chi-dao/${encodeURIComponent(row.id)}${qs}`);
    },
    [selectActiveRow, navigate],
  );

  const openCreate = useCallback(() => {
    if (!perms.canCreate) return;
    navigate('/chi-dao/tao-moi');
  }, [perms.canCreate, navigate]);

  const reloadAll = useCallback(() => {
    setLoadingMode('filter');
    load();
  }, [load, setLoadingMode]);

  const handlePageChange = useCallback((next: number) => {
    setPage(next);
  }, []);

  const handlePageSizeChange = useCallback((next: number) => {
    setPageSize(next);
    setPage(1);
  }, []);

  const handleHistoryToolbar = useCallback(() => {
    if (!activeRow) {
      dispatchAppToast(dispatch, {
        message: 'Chọn một dòng (menu dòng) rồi mở Lịch sử.',
        type: 'info',
      });
      return;
    }
    catalogHistory.openHistory({
      documentType: PAGE_ID,
      documentId: activeRow.id,
      documentCode: activeRow.code,
    });
  }, [activeRow, catalogHistory.openHistory, dispatch]);

  const openConfig = useCallback(() => {
    setConfigOpen(true);
  }, []);

  const deleteRow = useCallback(
    async (row: NotificationDto) => {
      if (!perms.canDelete) {
        window.alert('Không có quyền xóa chỉ đạo.');
        return;
      }
      if (!window.confirm(`Xóa chỉ đạo «${row.code} — ${row.title}»?`)) {
        return;
      }
      try {
        await notificationService.delete(row.id);
        clearSelection();
        setLoadingMode('filter');
        load();
      } catch (err) {
        window.alert(err instanceof Error ? err.message : 'Xóa chỉ đạo thất bại.');
      }
    },
    [perms.canDelete, clearSelection, setLoadingMode, load],
  );

  const markReadRow = useCallback(
    async (row: NotificationDto) => {
      try {
        await notificationService.markRead(row.id);
        setLoadingMode('filter');
        load();
      } catch {
        window.alert('Đánh dấu đã đọc thất bại.');
      }
    },
    [setLoadingMode, load],
  );

  const markAllRead = useCallback(async () => {
    try {
      await notificationService.markAllRead();
      setLoadingMode('filter');
      load();
    } catch {
      window.alert('Đánh dấu tất cả đã đọc thất bại.');
    }
  }, [setLoadingMode, load]);

  const catalogToolbar = useMemo(
    () => ({
      testIdPrefix: TEST_ID,
      onRefresh: reloadAll,
      canAdd: perms.canCreate,
      onAdd: openCreate,
      canHistory: true,
      onHistory: handleHistoryToolbar,
      showSchemaConfig: true,
      onEditConfig: openConfig,
      showEdit: Boolean(activeRow && perms.canUpdate),
      showView: Boolean(activeRow && perms.canRead),
      onEdit: activeRow ? () => openRow(activeRow, 'edit') : undefined,
      onView: activeRow ? () => openRow(activeRow, 'view') : undefined,
      canDelete: Boolean(activeRow && perms.canDelete),
      onDelete: activeRow
        ? () => {
            void deleteRow(activeRow);
          }
        : undefined,
    }),
    [
      reloadAll,
      perms.canCreate,
      perms.canUpdate,
      perms.canRead,
      perms.canDelete,
      openCreate,
      handleHistoryToolbar,
      openConfig,
      activeRow,
      openRow,
      deleteRow,
    ],
  );

  const listFilters = useMemo(
    () => (
      <ErpListHeaderFilters testIdPrefix={TEST_ID} filterCols={4}>
        <LinListFilterField testId={`${TEST_ID}-field-search`}>
          <SearchTextInput
            label="Tìm kiếm"
            placeholder="Mã · tiêu đề · đội…"
            value={searchDraft}
            onChange={setSearchDraft}
            onSearch={() =>
              applyFilters(
                searchDraft,
                statusDraft,
                priorityDraft,
                typeDraft,
                unreadDraft,
                directionDraft,
                orgDraft,
              )
            }
            testId={`${TEST_ID}-search-text`}
          />
        </LinListFilterField>
        <LinListFilterField testId={`${TEST_ID}-field-status`}>
          <SearchInput
            label="Trạng thái"
            config={STATUS_LOOKUP_CONFIG}
            value={statusDraft}
            primaryDisplay={lookupLabel(STATUS_LOOKUP, statusDraft)}
            showSecondaryInput={false}
            placeholder="Tất cả trạng thái"
            onChange={(item) => setStatusDraft(item.value)}
            onClear={() => setStatusDraft('')}
          />
        </LinListFilterField>
        <LinListFilterField testId={`${TEST_ID}-field-priority`}>
          <SearchInput
            label="Ưu tiên"
            config={PRIORITY_LOOKUP_CONFIG}
            value={priorityDraft}
            primaryDisplay={lookupLabel(PRIORITY_LOOKUP, priorityDraft)}
            showSecondaryInput={false}
            placeholder="Tất cả ưu tiên"
            onChange={(item) => setPriorityDraft(item.value)}
            onClear={() => setPriorityDraft('')}
          />
        </LinListFilterField>
        <LinListFilterField testId={`${TEST_ID}-field-type`}>
          <SearchInput
            label="Loại"
            config={TYPE_LOOKUP_CONFIG}
            value={typeDraft}
            primaryDisplay={lookupLabel(TYPE_LOOKUP, typeDraft)}
            showSecondaryInput={false}
            placeholder="Tất cả loại"
            onChange={(item) => setTypeDraft(item.value)}
            onClear={() => setTypeDraft('')}
          />
        </LinListFilterField>
        <LinListFilterField testId={`${TEST_ID}-field-direction`}>
          <SearchInput
            label="Chiều"
            config={DIRECTION_LOOKUP_CONFIG}
            value={directionDraft}
            primaryDisplay={lookupLabel(DIRECTION_LOOKUP, directionDraft)}
            showSecondaryInput={false}
            placeholder="Tất cả chiều"
            onChange={(item) => setDirectionDraft(item.value)}
            onClear={() => setDirectionDraft('')}
          />
        </LinListFilterField>
        <LinListFilterField testId={`${TEST_ID}-field-org`}>
          <SearchInput
            label="Đơn vị"
            config={ORG_UNIT_LOOKUP_CONFIG}
            value={orgDraft}
            primaryDisplay={lookupLabel(ORG_UNIT_LOOKUP, orgDraft)}
            showSecondaryInput={false}
            placeholder="Tất cả đơn vị"
            onChange={(item) => setOrgDraft(item.value)}
            onClear={() => setOrgDraft('')}
          />
        </LinListFilterField>
      </ErpListHeaderFilters>
    ),
    [
      searchDraft,
      statusDraft,
      priorityDraft,
      typeDraft,
      unreadDraft,
      directionDraft,
      orgDraft,
      applyFilters,
    ],
  );

  const uiColumns = useMemo<UiListColumnBootstrap<NotificationDto>[]>(
    () => [
      {
        key: 'code',
        label: 'Mã',
        width: '10rem',
        allowSort: true,
        render: (row) => (
          <button
            type="button"
            className={styles.codeLink}
            onClick={() => openRow(row, perms.canUpdate ? 'edit' : 'view')}
            data-testid={`${TEST_ID}-code-${row.code}`}
          >
            {row.code}
          </button>
        ),
        getDisplayValue: (r) => r.code,
      },
      {
        key: 'documentNumber',
        label: 'Số CV',
        width: '8rem',
        allowSort: true,
        render: (row) => row.documentNumber || '—',
        getDisplayValue: (r) => r.documentNumber || '',
      },
      {
        key: 'direction',
        label: 'Chiều',
        width: '6rem',
        control: 'SELECT',
        allowSort: true,
        render: (row) => lookupLabel(DIRECTION_LOOKUP, row.direction || ''),
        getDisplayValue: (r) => r.direction || '',
      },
      {
        key: 'summary',
        label: 'Trích yếu',
        width: '14rem',
        allowSort: true,
        render: (row) => row.summary || '—',
        getDisplayValue: (r) => r.summary || '',
      },
      {
        key: 'orgUnitName',
        label: 'Đơn vị',
        width: '10rem',
        allowSort: true,
        render: (row) =>
          row.orgUnitName || lookupLabel(ORG_UNIT_LOOKUP, row.orgUnitCode || '') || '—',
        getDisplayValue: (r) => r.orgUnitName || r.orgUnitCode || '',
      },
      {
        key: 'title',
        label: 'Tiêu đề',
        width: '14rem',
        allowSort: true,
        render: (row) => (
          <span className={row.isUnread ? styles.unreadTitle : undefined}>
            {row.title}
          </span>
        ),
        getDisplayValue: (r) => r.title,
      },
      {
        key: 'sender',
        label: 'Người gửi',
        width: '8rem',
        allowSort: true,
        render: (row) => row.sender || '—',
        getDisplayValue: (r) => r.sender || '',
      },
      {
        key: 'recipient',
        label: 'Người nhận',
        width: '8rem',
        control: 'SELECT',
        allowSort: true,
        render: (row) => lookupLabel(RECIPIENT_LOOKUP, row.recipient),
        getDisplayValue: (r) => r.recipient,
      },
      {
        key: 'priority',
        label: 'Ưu tiên',
        width: '7rem',
        control: 'SELECT',
        allowSort: true,
        render: (row) => lookupLabel(PRIORITY_LOOKUP, row.priority || ''),
        getDisplayValue: (r) => r.priority || '',
      },
      {
        key: 'type',
        label: 'Loại',
        width: '7rem',
        control: 'SELECT',
        allowSort: true,
        render: (row) => lookupLabel(TYPE_LOOKUP, row.type || ''),
        getDisplayValue: (r) => r.type || '',
      },
      {
        key: 'status',
        label: 'TT',
        width: '7rem',
        control: 'SELECT',
        allowSort: true,
        render: (row) => lookupLabel(STATUS_LOOKUP, row.status),
        getDisplayValue: (r) => r.status,
      },
      {
        key: 'sentAt',
        label: 'Thời gian',
        width: '10rem',
        control: 'DATE',
        allowSort: true,
        render: (row) => formatSentAt(row.sentAt),
        getDisplayValue: (r) => r.sentAt || '',
      },
    ],
    [openRow, perms.canUpdate],
  );

  const gridColumns = useMemo(
    () => buildDynamicGridColumns(schema, uiColumns),
    [schema, uiColumns],
  );

  useEffect(() => {
    if (!schema?.list) return;
    setTableConfig({
      ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
      ...catalogListTableConfigFromSchema(schema.list),
      resizable: true,
    });
  }, [schema]);

  const rowMenuItems = useMemo<LinCatalogRowMenuItem[]>(() => {
    const base = buildCatalogRowMenuItems({
      showView: perms.canRead,
      showEdit: perms.canUpdate,
      showCopy: perms.canCreate,
      showHistory: perms.canRead,
      showDelete: perms.canDelete,
    });
    const extras: LinCatalogRowMenuItem[] = [
      {
        id: 'mark-read',
        label: 'Đánh dấu đã đọc',
        icon: 'fas fa-envelope-open',
        separatorBefore: true,
      },
      {
        id: 'assign',
        label: 'Giao việc (P2)',
        icon: 'fas fa-user-plus',
      },
    ];
    return [...base, ...extras];
  }, [perms.canRead, perms.canUpdate, perms.canCreate, perms.canDelete]);

  const handleRowMenuSelect = useCallback(
    (action: string) => {
      const row = rowMenu?.row;
      setRowMenu(null);
      if (!row) return;
      switch (action) {
        case 'view':
          openRow(row, 'view');
          break;
        case 'edit':
          openRow(row, 'edit');
          break;
        case 'copy':
          openRow(row, 'copy');
          break;
        case 'delete':
          void deleteRow(row);
          break;
        case 'history':
          catalogHistory.openHistory({
            documentType: PAGE_ID,
            documentId: row.id,
            documentCode: row.code,
          });
          break;
        case 'mark-read':
          void markReadRow(row);
          break;
        case 'assign':
          window.alert(`Giao việc ${row.code} — DEFER P2.`);
          break;
        default:
          break;
      }
    },
    [rowMenu?.row, openRow, deleteRow, markReadRow, catalogHistory.openHistory],
  );

  const emptyMessage =
    search.trim() ||
    statusFilter ||
    priorityFilter ||
    typeFilter ||
    unreadOnly ||
    directionFilter ||
    orgFilter
      ? 'Không có chỉ đạo phù hợp bộ lọc.'
      : 'Không có dữ liệu chỉ đạo điều hành.';

  const beforeToolbar = (
    <>
      <div className={styles.kpiStrip} data-testid={`${TEST_ID}-kpi`}>
        <div className={styles.kpi}>
          <div className={styles.kpiLabel}>Cán bộ online</div>
          <div className={styles.kpiValue}>{overview.staffOnline}</div>
        </div>
        <div className={styles.kpi}>
          <div className={styles.kpiLabel}>Sự cố mở</div>
          <div className={styles.kpiValue}>{overview.openIncidents}</div>
        </div>
        <div className={styles.kpi}>
          <div className={styles.kpiLabel}>WO đang SC</div>
          <div className={styles.kpiValue}>{overview.woInProgress}</div>
        </div>
        <div className={styles.kpi}>
          <div className={styles.kpiLabel}>Chưa đọc</div>
          <div className={styles.kpiValue}>{overview.unreadCount}</div>
        </div>
      </div>
      <div className={styles.extraBar} data-testid={`${TEST_ID}-extra-actions`}>
        <Button
          type="button"
          variant="secondary"
          size="sm"
          onClick={() => setUnreadDraft(unreadDraft === '1' ? '' : '1')}
          data-testid={`${TEST_ID}-unread-toggle`}
        >
          {unreadDraft === '1' ? 'Bỏ lọc chưa đọc' : 'Lọc chưa đọc'}
        </Button>
        <Button type="button" variant="secondary" size="sm" onClick={() => void markAllRead()}>
          Đánh dấu tất cả đã đọc
        </Button>
        <Button
          type="button"
          variant="secondary"
          size="sm"
          onClick={() => window.alert('Xuất inbox — stub P1.')}
        >
          Xuất
        </Button>
        <Button
          type="button"
          variant="secondary"
          size="sm"
          onClick={() => window.alert('Navigate → Giám sát (patrol) — cross-MFE stub.')}
        >
          Giám sát
        </Button>
        <Button
          type="button"
          variant="secondary"
          size="sm"
          onClick={() => window.alert('Navigate → Bản đồ (gis) — cross-MFE stub.')}
        >
          Bản đồ
        </Button>
        <Button
          type="button"
          variant="secondary"
          size="sm"
          onClick={() => window.alert('Navigate → Sự cố (incident) — cross-MFE stub.')}
        >
          Sự cố
        </Button>
        <Button
          type="button"
          variant="secondary"
          size="sm"
          onClick={() =>
            window.alert('Command center — DEFER P2 (GAP-F-OPS-01).')
          }
        >
          Command <span className={styles.badgeP2}>P2</span>
        </Button>
      </div>
    </>
  );

  return (
    <div
      className={styles.page}
      data-catalog-list-page
      data-testid={`${TEST_ID}-page`}
    >
      <LinPageLayout
        kind="catalog"
        filterBarLayout="standard"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        header={{
          title: 'Chỉ đạo điều hành',
          titleIconClass: 'fas fa-bullhorn',
          pageId: PAGE_ID,
        }}
        beforeToolbar={beforeToolbar}
        toolbar={fromCatalogToolbar(catalogToolbar)}
        listTitle="Danh sách chỉ đạo / thông báo"
        listRowMenuHelp
        filters={listFilters}
        filtersTestId={`${TEST_ID}-filters`}
        showTableLoading={showTableLoading}
        pageLoading={pageLoading}
        skeletonRows={8}
        footer={
          <LinCatalogListPagination
            testIdPrefix={TEST_ID}
            page={page}
            pageSize={pageSize}
            totalCount={totalCount}
            onPageChange={handlePageChange}
            onPageSizeChange={handlePageSizeChange}
          />
        }
        modals={
          <>
            <LinCatalogRowActionMenu
              open={rowMenu != null}
              x={rowMenu?.x ?? 0}
              y={rowMenu?.y ?? 0}
              testIdPrefix={TEST_ID}
              onClose={() => setRowMenu(null)}
              onSelect={(action) => {
                handleRowMenuSelect(action);
              }}
              items={rowMenuItems}
            />
            <LinCatalogUiSchemaEditorModal
              isOpen={configOpen}
              onClose={() => setConfigOpen(false)}
              testIdPrefix={TEST_ID}
              catalogKind={CATALOG_KIND}
              loadSchema={catalogUiSchemaService.get}
              saveSchema={catalogUiSchemaService.save}
              onSaved={(next) => {
                setTableConfig({
                  ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
                  ...catalogListTableConfigFromSchema(next.list),
                  resizable: true,
                });
                reloadSchema();
                setConfigOpen(false);
              }}
              onError={(message) =>
                dispatchAppToast(dispatch, { message, type: 'error' })
              }
              onSuccess={(message) =>
                dispatchAppToast(dispatch, { message, type: 'success' })
              }
            />
            {catalogHistory.modalProps ? (
              <LinCatalogHistoryModal
                {...catalogHistory.modalProps}
                testIdPrefix={TEST_ID}
                onError={(message) =>
                  dispatchAppToast(dispatch, { message, type: 'error' })
                }
              />
            ) : null}
          </>
        }
      >
        <div className={styles.gridWrap} data-testid={`${TEST_ID}-grid-wrap`}>
          <LinCatalogDataGrid
            testIdPrefix={TEST_ID}
            rows={items}
            page={page}
            pageSize={pageSize}
            columns={gridColumns}
            getRowId={(r) => r.id}
            selection={listSelection}
            tableConfig={tableConfig}
            paginateClient={false}
            empty={
              <div className={styles.empty} data-testid={`${TEST_ID}-empty`}>
                {emptyMessage}
              </div>
            }
            onRowOpenActionMenu={({ row, x, y }) => {
              selectActiveRow(row);
              setRowMenu({ row, x, y });
            }}
            onRowDoubleClick={(row) => openRow(row, 'view')}
            rowMenuHintDismissStorageKey={ROW_MENU_HINT_KEY}
          />
        </div>
      </LinPageLayout>
    </div>
  );
};

export default NotificationListPage;
