import type { SearchInputConfig } from '@linm-soft-org/linm-web-common-components';
import {
  SEARCH_DROPDOWN_PORTAL,
  catalogLookupColumns,
  catalogLookupHeader,
} from '../../search/searchDropdownDefaults';
import {
  OPS_CHANNELS,
  OPS_DIRECTIONS,
  OPS_ORG_UNITS,
  OPS_PRIORITIES,
  OPS_RECIPIENTS,
  OPS_STATUSES,
  OPS_TYPES,
} from '../../demo/opsStore';

export type MasterLookupItem = {
  value: string;
  label: string;
};

export const STATUS_LOOKUP: MasterLookupItem[] = OPS_STATUSES.map((s) => ({
  value: s.value,
  label: s.label,
}));

export const PRIORITY_LOOKUP: MasterLookupItem[] = OPS_PRIORITIES.map((s) => ({
  value: s.value,
  label: s.label,
}));

export const TYPE_LOOKUP: MasterLookupItem[] = OPS_TYPES.map((s) => ({
  value: s.value,
  label: s.label,
}));

export const CHANNEL_LOOKUP: MasterLookupItem[] = OPS_CHANNELS.map((s) => ({
  value: s.value,
  label: s.label,
}));

export const RECIPIENT_LOOKUP: MasterLookupItem[] = OPS_RECIPIENTS.map((s) => ({
  value: s.value,
  label: s.label,
}));

function searchMaster(
  items: MasterLookupItem[],
  search?: string,
): { items: MasterLookupItem[]; page: number; totalPages: number } {
  const q = (search ?? '').trim().toLowerCase();
  const filtered = q
    ? items.filter(
        (i) =>
          i.value.toLowerCase().includes(q) || i.label.toLowerCase().includes(q),
      )
    : items;
  return { items: filtered, page: 1, totalPages: 1 };
}

export function masterLookupConfig(
  items: MasterLookupItem[],
): SearchInputConfig<MasterLookupItem> {
  return {
    api: {
      getItemKey: (i) => i.value,
      search: async ({ search }) => searchMaster(items, search),
      getDetail: async (id) =>
        items.find((i) => i.value === id) ?? { value: id, label: id },
    },
    display: {
      getPrimaryDisplay: (i) => i.label,
      getSecondaryDisplay: (i) => i.label,
      getSingleDisplay: (i) => i.label,
    },
    ...SEARCH_DROPDOWN_PORTAL,
    columns: catalogLookupColumns(),
    header: catalogLookupHeader(),
    pageSize: 50,
  };
}

export const STATUS_LOOKUP_CONFIG = masterLookupConfig(STATUS_LOOKUP);
export const PRIORITY_LOOKUP_CONFIG = masterLookupConfig(PRIORITY_LOOKUP);
export const TYPE_LOOKUP_CONFIG = masterLookupConfig(TYPE_LOOKUP);
export const CHANNEL_LOOKUP_CONFIG = masterLookupConfig(CHANNEL_LOOKUP);
export const RECIPIENT_LOOKUP_CONFIG = masterLookupConfig(RECIPIENT_LOOKUP);

export const DIRECTION_LOOKUP: MasterLookupItem[] = OPS_DIRECTIONS.map((s) => ({
  value: s.value,
  label: s.label,
}));

export const ORG_UNIT_LOOKUP: MasterLookupItem[] = OPS_ORG_UNITS.map((s) => ({
  value: s.value,
  label: s.label,
}));

export const DIRECTION_LOOKUP_CONFIG = masterLookupConfig(DIRECTION_LOOKUP);
export const ORG_UNIT_LOOKUP_CONFIG = masterLookupConfig(ORG_UNIT_LOOKUP);

export function lookupLabel(items: MasterLookupItem[], value: string): string {
  return items.find((i) => i.value === value)?.label ?? value;
}
